1	import type { NoteEntry, VisibleNavigationItem } from "@/shared/types";
2	import type { NotePreview } from "@/shared/lib/format";
3	
4	// Feed is not the folder tree. It is a synthetic hierarchy built from note
5	// timestamps so the navigation UI can browse recent work by time bucket.
6	export type FeedTreeNodeKind =
7	  | "special"
8	  | "year"
9	  | "quarter"
10	  | "month"
11	  | "week"
12	  | "day"
13	  | "undated";
14	
15	export type FeedTreeNode = {
16	  id: string;
17	  name: string;
18	  kind: FeedTreeNodeKind;
19	  parentId: string | null;
20	  rangeStartMs: number | null;
21	  rangeEndMs: number | null;
22	  children: FeedTreeNode[];
23	  notes: Array<NoteEntry & { timestampMs: number }>;
24	  noteCount: number;
25	  latestMs: number;
26	  rank: number;
27	};
28	
29	export type FeedTreeBuildResult = {
30	  treeData: FeedTreeNode[];
31	  nodeById: Map<string, FeedTreeNode>;
32	};
33	
34	type FeedNodeBuilder = {
35	  id: string;
36	  name: string;
37	  kind: FeedTreeNodeKind;
38	  parentId: string | null;
39	  rangeStartMs: number | null;
40	  rangeEndMs: number | null;
41	  children: Map<string, FeedNodeBuilder>;
42	  notes: Array<NoteEntry & { timestampMs: number }>;
43	  latestMs: number;
44	  rank: number;
45	};
46	
47	const DAY_MS = 86_400_000;
48	
49	const SPECIAL_GROUP_ORDER: Record<string, number> = {
50	  today: 0,
51	  yesterday: 1,
52	  "last-week": 2,
53	  undated: 99_999,
54	};
55	
56	const getWeekdayOrder = (date: Date) => (date.getDay() + 6) % 7;
57	
58	const createBuilder = (
59	  id: string,
60	  name: string,
61	  kind: FeedTreeNodeKind,
62	  parentId: string | null,
63	  rank: number,
64	  rangeStartMs: number | null = null,
65	  rangeEndMs: number | null = null
66	): FeedNodeBuilder => ({
67	  id,
68	  name,
69	  kind,
70	  parentId,
71	  rangeStartMs,
72	  rangeEndMs,
73	  children: new Map(),
74	  notes: [],
75	  latestMs: 0,
76	  rank,
77	});
78	
79	const ensureBuilder = (
80	  parent: FeedNodeBuilder,
81	  id: string,
82	  name: string,
83	  kind: FeedTreeNodeKind,
84	  rank: number,
85	  rangeStartMs: number | null = null,
86	  rangeEndMs: number | null = null
87	) => {
88	  const existing = parent.children.get(id);
89	  if (existing) {
90	    return existing;
91	  }
92	  const next = createBuilder(
93	    id,
94	    name,
95	    kind,
96	    parent.id,
97	    rank,
98	    rangeStartMs,
99	    rangeEndMs
100	  );
101	  parent.children.set(id, next);
102	  return next;
103	};
104	
105	const getStartOfDayMs = (date: Date) => {
106	  const value = new Date(date.getFullYear(), date.getMonth(), date.getDate());
107	  return value.getTime();
108	};
109	
110	const getEndOfDayMs = (date: Date) =>
111	  new Date(
112	    date.getFullYear(),
113	    date.getMonth(),
114	    date.getDate(),
115	    23,
116	    59,
117	    59,
118	    999
119	  ).getTime();
120	
121	type FeedDateRange = {
122	  rangeStartMs: number;
123	  rangeEndMs: number;
124	};
125	
126	const clampRangeEnd = (rangeEndMs: number, now: Date) =>
127	  Math.min(rangeEndMs, now.getTime());
128	
129	const getDayRange = (date: Date, now: Date): FeedDateRange => ({
130	  rangeStartMs: getStartOfDayMs(date),
131	  rangeEndMs: clampRangeEnd(getEndOfDayMs(date), now),
132	});
133	
134	const getMonthRange = (date: Date, now: Date): FeedDateRange => ({
135	  rangeStartMs: new Date(date.getFullYear(), date.getMonth(), 1).getTime(),
136	  rangeEndMs: clampRangeEnd(
137	    new Date(
138	      date.getFullYear(),
139	      date.getMonth() + 1,
140	      0,
141	      23,
142	      59,
143	      59,
144	      999
145	    ).getTime(),
146	    now
147	  ),
148	});
149	
150	const getYearRange = (date: Date, now: Date): FeedDateRange => ({
151	  rangeStartMs: new Date(date.getFullYear(), 0, 1).getTime(),
152	  rangeEndMs: clampRangeEnd(
153	    new Date(date.getFullYear(), 11, 31, 23, 59, 59, 999).getTime(),
154	    now
155	  ),
156	});
157	
158	const getFirstMondayDay = (date: Date) =>
159	  1 + ((8 - new Date(date.getFullYear(), date.getMonth(), 1).getDay()) % 7);
160	
161	const getWeekOfMonth = (date: Date) => {
162	  const firstMonday = getFirstMondayDay(date);
163	  if (date.getDate() < firstMonday) {
164	    return 0;
165	  }
166	  return Math.floor((date.getDate() - firstMonday) / 7) + 1;
167	};
168	
169	const getWeekDateBounds = (date: Date, week = getWeekOfMonth(date)) => {
170	  const firstMonday = getFirstMondayDay(date);
171	  const startDay = week === 0 ? 1 : firstMonday + (week - 1) * 7;
172	  const endDay = Math.min(
173	    week === 0 ? firstMonday - 1 : startDay + 6,
174	    new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate()
175	  );
176	  return {
177	    week,
178	    start: new Date(date.getFullYear(), date.getMonth(), startDay),
179	    end: new Date(
180	      date.getFullYear(),
181	      date.getMonth(),
182	      endDay,
183	      23,
184	      59,
185	      59,
186	      999
187	    ),
188	  };
189	};
190	
191	const getWeekRange = (date: Date, now: Date): FeedDateRange => {
192	  const { start, end } = getWeekDateBounds(date);
193	  return {
194	    rangeStartMs: start.getTime(),
195	    rangeEndMs: clampRangeEnd(end.getTime(), now),
196	  };
197	};
198	
199	const getWeekRangeLabel = (date: Date, week = getWeekOfMonth(date)) => {
200	  const { start, end } = getWeekDateBounds(date, week);
201	  const formatDate = (value: Date) =>
202	    value.toLocaleDateString([], {
203	      month: "long",
204	      day: "numeric",
205	    });
206	  const prefix = week === 0 ? "Month start" : `Week ${week}`;
207	  return `${prefix} (${formatDate(start)} - ${formatDate(end)})`;
208	};
209	
210	const getQuarter = (date: Date) => Math.floor(date.getMonth() / 3) + 1;
211	
212	const getQuarterRange = (date: Date, now: Date): FeedDateRange => {
213	  const firstMonth = (getQuarter(date) - 1) * 3;
214	  return {
215	    rangeStartMs: new Date(date.getFullYear(), firstMonth, 1).getTime(),
216	    rangeEndMs: clampRangeEnd(
217	      new Date(
218	        date.getFullYear(),
219	        firstMonth + 3,
220	        0,
221	        23,
222	        59,
223	        59,
224	        999
225	      ).getTime(),
226	      now
227	    ),
228	  };
229	};
230	
231	const getQuarterSortRank = (quarter: number) => 4 - quarter;
232	
233	const getMonthSortRank = (date: Date) => 12 - (date.getMonth() + 1);
234	
235	const getYearSortRank = (year: number) => 10_000 - year;
236	
237	const titleCase = (value: string) =>
238	  value.length > 0 ? value[0].toUpperCase() + value.slice(1) : value;
239	
240	const getMonthLabel = (date: Date) =>
241	  date.toLocaleDateString([], {
242	    month: "long",
243	  });
244	
245	const getWeekdayLabel = (date: Date) =>
246	  titleCase(
247	    date.toLocaleDateString([], {
248	      weekday: "long",
249	    })
250	  );
251	
252	const getSpecialLabel = (kind: "today" | "yesterday" | "last-week" | "undated") => {
253	  if (kind === "today") return "Today";
254	  if (kind === "yesterday") return "Yesterday";
255	  if (kind === "last-week") return "Last week";
256	  return "Undated";
257	};
258	
259	const buildPathSegments = (segments: Array<string | number>) =>
260	  `feed:${segments.map((segment) => String(segment)).join(":")}`;
261	
262	const getUndatedNode = (root: FeedNodeBuilder) =>
263	  ensureBuilder(
264	    root,
265	    buildPathSegments(["undated"]),
266	    getSpecialLabel("undated"),
267	    "undated",
268	    SPECIAL_GROUP_ORDER.undated
269	  );
270	
271	const addNoteToBuilder = (builder: FeedNodeBuilder, note: NoteEntry, timestampMs: number) => {
272	  builder.notes.push({ ...note, timestampMs });
273	  if (timestampMs > builder.latestMs) {
274	    builder.latestMs = timestampMs;
275	  }
276	};
277	
278	const addNoteToMonth = (
279	  month: FeedNodeBuilder,
280	  monthPathSegments: Array<string | number>,
281	  note: NoteEntry,
282	  timestampMs: number,
283	  date: Date,
284	  now: Date
285	) => {
286	  const week = getWeekOfMonth(date);
287	  const weekPathSegments = [...monthPathSegments, "week", week];
288	  const weekRange = getWeekRange(date, now);
289	  const weekNode = ensureBuilder(
290	    month,
291	    buildPathSegments(weekPathSegments),
292	    getWeekRangeLabel(date),
293	    "week",
294	    week,
295	    weekRange.rangeStartMs,
296	    weekRange.rangeEndMs
297	  );
298	  const dayRange = getDayRange(date, now);
299	  const dayNode = ensureBuilder(
300	    weekNode,
301	    buildPathSegments([...weekPathSegments, "day", date.getDate()]),
302	    getWeekdayLabel(date),
303	    "day",
304	    date.getDate(),
305	    dayRange.rangeStartMs,
306	    dayRange.rangeEndMs
307	  );
308	  addNoteToBuilder(dayNode, note, timestampMs);
309	};
310	
311	const ensureMonthCalendar = (
312	  month: FeedNodeBuilder,
313	  monthPathSegments: Array<string | number>,
314	  date: Date,
315	  now: Date
316	) => {
317	  const monthEndDay = new Date(
318	    date.getFullYear(),
319	    date.getMonth() + 1,
320	    0
321	  ).getDate();
322	  const visibleEndDay =
323	    date.getFullYear() === now.getFullYear() &&
324	    date.getMonth() === now.getMonth()
325	      ? Math.min(monthEndDay, now.getDate())
326	      : monthEndDay;
327	  const firstMonday = getFirstMondayDay(date);
328	  const firstWeek = firstMonday > 1 ? 0 : 1;
329	  const lastWeek = getWeekOfMonth(
330	    new Date(date.getFullYear(), date.getMonth(), visibleEndDay)
331	  );
332	
333	  for (let week = firstWeek; week <= lastWeek; week += 1) {
334	    const bounds = getWeekDateBounds(date, week);
335	    if (bounds.start.getDate() > visibleEndDay) {
336	      break;
337	    }
338	    const endDay = Math.min(bounds.end.getDate(), visibleEndDay);
339	    const rangeDate = new Date(
340	      date.getFullYear(),
341	      date.getMonth(),
342	      bounds.start.getDate()
343	    );
344	    const weekPathSegments = [...monthPathSegments, "week", week];
345	    const weekRange = getWeekRange(rangeDate, now);
346	    const weekNode = ensureBuilder(
347	      month,
348	      buildPathSegments(weekPathSegments),
349	      getWeekRangeLabel(date, week),
350	      "week",
351	      week,
352	      weekRange.rangeStartMs,
353	      Math.min(
354	        weekRange.rangeEndMs,
355	        getEndOfDayMs(
356	          new Date(date.getFullYear(), date.getMonth(), endDay)
357	        )
358	      )
359	    );
360	
361	    for (
362	      let day = bounds.start.getDate();
363	      day <= endDay;
364	      day += 1
365	    ) {
366	      const dayDate = new Date(date.getFullYear(), date.getMonth(), day);
367	      const dayRange = getDayRange(dayDate, now);
368	      ensureBuilder(
369	        weekNode,
370	        buildPathSegments([...weekPathSegments, "day", day]),
371	        getWeekdayLabel(dayDate),
372	        "day",
373	        day,
374	        dayRange.rangeStartMs,
375	        dayRange.rangeEndMs
376	      );
377	    }
378	  }
379	};
380	
381	const finalizeBuilder = (builder: FeedNodeBuilder): FeedTreeNode => {
382	  const children = [...builder.children.values()]
383	    .map((child) => finalizeBuilder(child))
384	    .sort((left, right) => {
385	      if (left.rank !== right.rank) {
386	        return left.rank - right.rank;
387	      }
388	      if (left.latestMs !== right.latestMs) {
389	        return right.latestMs - left.latestMs;
390	      }
391	      return left.name.localeCompare(right.name);
392	    });
393	  const noteCount = builder.notes.length + children.reduce((total, child) => total + child.noteCount, 0);
394	  return {
395	    id: builder.id,
396	    name: builder.name,
397	    kind: builder.kind,
398	    parentId: builder.parentId,
399	    rangeStartMs: builder.rangeStartMs,
400	    rangeEndMs: builder.rangeEndMs,
401	    children,
402	    notes: [...builder.notes].sort((left, right) => {
403	      if (left.timestampMs !== right.timestampMs) {
404	        return right.timestampMs - left.timestampMs;
405	      }
406	      return left.name.localeCompare(right.name);
407	    }),
408	    noteCount,
409	    latestMs: builder.latestMs,
410	    rank: builder.rank,
411	  };
412	};
413	
414	const getFeedTimestamp = (preview?: NotePreview) =>
415	  preview?.createdMs ?? preview?.updatedMs ?? null;
416	
417	const addRecentNote = (
418	  root: FeedNodeBuilder,
419	  note: NoteEntry,
420	  timestampMs: number,
421	  now: Date
422	) => {
423	  const date = new Date(timestampMs);
424	  const ageDays = Math.floor(
425	    (getStartOfDayMs(now) - getStartOfDayMs(date)) / DAY_MS
426	  );
427	  if (ageDays <= 0) {
428	    const todayRange = getDayRange(now, now);
429	    const today = ensureBuilder(
430	      root,
431	      buildPathSegments(["today"]),
432	      getSpecialLabel("today"),
433	      "special",
434	      SPECIAL_GROUP_ORDER.today,
435	      todayRange.rangeStartMs,
436	      todayRange.rangeEndMs
437	    );
438	    addNoteToBuilder(today, note, timestampMs);
439	    return;
440	  }
441	
442	  if (ageDays === 1) {
443	    const yesterdayRange = getDayRange(date, now);
444	    const yesterday = ensureBuilder(
445	      root,
446	      buildPathSegments(["yesterday"]),
447	      getSpecialLabel("yesterday"),
448	      "special",
449	      SPECIAL_GROUP_ORDER.yesterday,
450	      yesterdayRange.rangeStartMs,
451	      yesterdayRange.rangeEndMs
452	    );
453	    addNoteToBuilder(yesterday, note, timestampMs);
454	    return;
455	  }
456	
457	  if (ageDays < 7) {
458	    const lastWeekStart = new Date(
459	      now.getFullYear(),
460	      now.getMonth(),
461	      now.getDate() - 6
462	    );
463	    const lastWeekEnd = new Date(
464	      now.getFullYear(),
465	      now.getMonth(),
466	      now.getDate() - 2,
467	      23,
468	      59,
469	      59,
470	      999
471	    );
472	    const lastWeek = ensureBuilder(
473	      root,
474	      buildPathSegments(["last-week"]),
475	      getSpecialLabel("last-week"),
476	      "special",
477	      SPECIAL_GROUP_ORDER["last-week"],
478	      lastWeekStart.getTime(),
479	      lastWeekEnd.getTime()
480	    );
481	    const dayId = buildPathSegments(["last-week", "day", date.getDay()]);
482	    const dayRange = getDayRange(date, now);
483	    const day = ensureBuilder(
484	      lastWeek,
485	      dayId,
486	      getWeekdayLabel(date),
487	      "day",
488	      getWeekdayOrder(date),
489	      dayRange.rangeStartMs,
490	      dayRange.rangeEndMs
491	    );
492	    addNoteToBuilder(day, note, timestampMs);
493	    return;
494	  }
495	
496	  if (date.getFullYear() === now.getFullYear()) {
497	    const monthPathSegments = [
498	      "month",
499	      date.getFullYear(),
500	      date.getMonth() + 1,
501	    ];
502	    const monthId = buildPathSegments(monthPathSegments);
503	    const monthRange = getMonthRange(date, now);
504	    const month = ensureBuilder(
505	      root,
506	      monthId,
507	      getMonthLabel(date),
508	      "month",
509	      10 + getMonthSortRank(date),
510	      monthRange.rangeStartMs,
511	      monthRange.rangeEndMs
512	    );
513	    ensureMonthCalendar(month, monthPathSegments, date, now);
514	    addNoteToMonth(month, monthPathSegments, note, timestampMs, date, now);
515	    return;
516	  }
517	
518	  const yearId = buildPathSegments(["year", date.getFullYear()]);
519	  const yearRange = getYearRange(date, now);
520	  const year = ensureBuilder(
521	    root,
522	    yearId,
523	    String(date.getFullYear()),
524	    "year",
525	    getYearSortRank(date.getFullYear()),
526	    yearRange.rangeStartMs,
527	    yearRange.rangeEndMs
528	  );
529	  const quarter = getQuarter(date);
530	  const quarterId = buildPathSegments(["year", date.getFullYear(), "quarter", quarter]);
531	  const quarterRange = getQuarterRange(date, now);
532	  const quarterNode = ensureBuilder(
533	    year,
534	    quarterId,
535	    `Q${quarter}`,
536	    "quarter",
537	    getQuarterSortRank(quarter),
538	    quarterRange.rangeStartMs,
539	    quarterRange.rangeEndMs
540	  );
541	  const monthPathSegments = [
542	    "year",
543	    date.getFullYear(),
544	    "quarter",
545	    quarter,
546	    "month",
547	    date.getMonth() + 1,
548	  ];
549	  const monthId = buildPathSegments(monthPathSegments);
550	  const monthRange = getMonthRange(date, now);
551	  const monthNode = ensureBuilder(
552	    quarterNode,
553	    monthId,
554	    getMonthLabel(date),
555	    "month",
556	    10 + getMonthSortRank(date),
557	    monthRange.rangeStartMs,
558	    monthRange.rangeEndMs
559	  );
560	  ensureMonthCalendar(monthNode, monthPathSegments, date, now);
561	  addNoteToMonth(monthNode, monthPathSegments, note, timestampMs, date, now);
562	};
563	
564	export function buildFeedTree(
565	  notes: NoteEntry[],
566	  previews: Record<string, NotePreview>,
567	  hideArchivedNotes: boolean
568	): FeedTreeBuildResult {
569	  const now = new Date();
570	  const root = createBuilder("feed:root", "Feed", "special", null, 0);
571	
572	  notes.forEach((note) => {
573	    const preview = previews[note.path];
574	    if (!preview) {
575	      return;
576	    }
577	    if (hideArchivedNotes && preview.isArchived) {
578	      return;
579	    }
580	    const timestampMs = getFeedTimestamp(preview);
581	    if (timestampMs == null) {
582	      const undated = getUndatedNode(root);
583	      addNoteToBuilder(undated, note, 0);
584	      return;
585	    }
586	    const date = new Date(timestampMs);
587	    if (Number.isNaN(date.getTime())) {
588	      addNoteToBuilder(getUndatedNode(root), note, 0);
589	      return;
590	    }
591	    addRecentNote(root, note, timestampMs, now);
592	  });
593	
594	  const treeData = [...root.children.values()]
595	    .map((child) => finalizeBuilder(child))
596	    .sort((left, right) => {
597	      if (left.rank !== right.rank) {
598	        return left.rank - right.rank;
599	      }
600	      if (left.latestMs !== right.latestMs) {
601	        return right.latestMs - left.latestMs;
602	      }
603	      return left.name.localeCompare(right.name);
604	    });
605	
606	  const nodeById = new Map<string, FeedTreeNode>();
607	  const walk = (node: FeedTreeNode) => {
608	    nodeById.set(node.id, node);
609	    node.children.forEach(walk);
610	  };
611	  treeData.forEach(walk);
612	  return { treeData, nodeById };
613	}
614	
615	export function buildVisibleFeedNavigationItems(
616	  treeData: FeedTreeNode[],
617	  expanded: Set<string>,
618	  shouldNestNotesInNavigation: boolean
619	): VisibleNavigationItem[] {
620	  const items: VisibleNavigationItem[] = [];
621	
622	  const walk = (nodes: FeedTreeNode[], parentId: string | null) => {
623	    nodes.forEach((node) => {
624	      items.push({
625	        type: "folder",
626	        id: node.id,
627	        parentId,
628	      });
629	
630	      const noteRows = shouldNestNotesInNavigation ? node.notes : [];
631	      const hasNestedItems = node.children.length > 0 || noteRows.length > 0;
632	      if (!hasNestedItems || !expanded.has(node.id)) {
633	        return;
634	      }
635	
636	      noteRows.forEach((note) => {
637	        items.push({
638	          type: "note",
639	          id: note.path,
640	          parentId: node.id,
641	        });
642	      });
643	
644	      walk(node.children, node.id);
645	    });
646	  };
647	
648	  walk(treeData, null);
649	  return items;
650	}
651	
652	export function collectFeedNotes(
653	  node: FeedTreeNode | null
654	): Array<NoteEntry & { timestampMs: number }> {
655	  if (!node) {
656	    return [];
657	  }
658	  const notes = [...node.notes]
659	    .sort((left, right) => {
660	      if (left.timestampMs !== right.timestampMs) {
661	        return right.timestampMs - left.timestampMs;
662	      }
663	      return left.name.localeCompare(right.name);
664	    });
665	  node.children.forEach((child) => {
666	    notes.push(...collectFeedNotes(child));
667	  });
668	  return notes.sort((left, right) => {
669	    if (left.timestampMs !== right.timestampMs) {
670	      return right.timestampMs - left.timestampMs;
671	    }
672	    return left.name.localeCompare(right.name);
673	  });
674	}
675	
676	export function getFirstFeedGroupId(treeData: FeedTreeNode[]): string {
677	  return treeData[0]?.id ?? "";
678	}
679	
680	export function findFeedNode(
681	  treeData: FeedTreeNode[],
682	  targetId: string
683	): FeedTreeNode | null {
684	  for (const node of treeData) {
685	    if (node.id === targetId) {
686	      return node;
687	    }
688	    const match = findFeedNode(node.children, targetId);
689	    if (match) {
690	      return match;
691	    }
692	  }
693	  return null;
694	}
695	
696	export function getLatestFeedTargetTimestamp(
697	  node: FeedTreeNode | null,
698	  now: Date = new Date()
699	): number | null {
700	  if (node?.rangeStartMs == null || node.rangeEndMs == null) {
701	    return null;
702	  }
703	  const latestMs = Math.min(node.rangeEndMs, now.getTime());
704	  return latestMs >= node.rangeStartMs ? latestMs : null;
705	}
