62	/// Resolve the active profile's notes root, creating the directory if needed.
63	pub(crate) fn notes_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
64	    let root = match ensure_profiles_state(app) {
65	        Ok(state) => {
66	            let active = find_profile(&state, &state.active_profile_id)
67	                .or_else(|| state.profiles.first())
68	                .ok_or_else(|| "No profiles configured.".to_string())?;
69	            PathBuf::from(&active.notes_root)
70	        }
71	        Err(_) => crate::legacy_notes_root(app)?,
72	    };
73	    if !root.exists() {
74	        fs::create_dir_all(&root).map_err(|err| err.to_string())?;
75	    }
76	    Ok(root)
77	}
