1	//! Folder tree construction, system folders, legacy migration, and order files.
2	
3	use std::{
4	    collections::HashMap,
5	    fs,
6	    path::{Path, PathBuf},
7	};
8	
9	use crate::time_to_ms;
10	
11	use super::*;
12	
13	// ── File collection ────────────────────────────────────────────────────────────
14	
15	/// Recursively collect all `.md` files, skipping hidden and storage folders.
16	pub(crate) fn collect_markdown_note_files(
17	    root: &Path,
18	    dir: &Path,
19	    files: &mut Vec<PathBuf>,
20	) -> Result<(), String> {
21	    for entry in fs::read_dir(dir).map_err(|error| error.to_string())? {
22	        let entry = entry.map_err(|error| error.to_string())?;
23	        let path = entry.path();
24	        let name = entry.file_name().to_string_lossy().to_string();
25	        if name == ORDER_FILE {
26	            continue;
27	        }
28	        let metadata = entry.metadata().map_err(|error| error.to_string())?;
29	        if metadata.is_dir() {
30	            if name.starts_with('.') {
31	                continue;
32	            }
33	            if dir == root {
34	                if HIDDEN_ROOT_FOLDERS.iter().any(|hidden| *hidden == name) {
35	                    continue;
36	                }
37	            }
38	            collect_markdown_note_files(root, &path, files)?;
39	            continue;
40	        }
41	        if metadata.is_file() && path.extension().and_then(|value| value.to_str()) == Some("md") {
42	            files.push(path);
43	        }
44	    }
45	    Ok(())
46	}
47	
48	// ── Ordering & sorting ─────────────────────────────────────────────────────────
49	
50	/// Sort names according to a persisted order list, alphabetical fallback.
51	pub(crate) fn sort_by_order(mut names: Vec<String>, order: &[String]) -> Vec<String> {
52	    let mut index = HashMap::new();
53	    for (idx, name) in order.iter().enumerate() {
54	        index.insert(name, idx);
55	    }
56	    names.sort_by(|a, b| {
57	        let a_idx = index.get(a).copied().unwrap_or(usize::MAX);
58	        let b_idx = index.get(b).copied().unwrap_or(usize::MAX);
59	        a_idx
60	            .cmp(&b_idx)
61	            .then_with(|| a.to_lowercase().cmp(&b.to_lowercase()))
62	    });
63	    names
64	}
65	
66	// ── Folder classification ──────────────────────────────────────────────────────
67	
68	/// True if the folder name matches a protected system folder.
69	pub(crate) fn is_system_folder_name(name: &str) -> bool {
70	    PROTECTED_SYSTEM_FOLDERS
71	        .iter()
72	        .any(|folder| *folder == name)
73	}
74	
75	/// True if the folder should be hidden from the tree at root level.
76	pub(crate) fn is_hidden_root_folder_name(name: &str) -> bool {
77	    HIDDEN_ROOT_FOLDERS.iter().any(|folder| *folder == name)
78	}
79	
80	/// True if the path is the Feed folder.
81	pub(crate) fn is_feed_folder_path(root: &Path, path: &Path) -> bool {
82	    path == root.join(FEED_FOLDER)
83	}
84	
85	/// Extract created_ms for Feed sort order (front-matter → fs metadata → 0).
86	fn note_created_ms_for_sort(path: &Path) -> i64 {
87	    if let Ok(raw) = fs::read_to_string(path) {
88	        let (meta, _) = parse_note_front_matter(&raw);
89	        if let Some(created_ms) = meta.created_ms {
90	            return created_ms;
91	        }
92	    }
93	    if let Ok(metadata) = fs::metadata(path) {
94	        if let Ok(created) = metadata.created() {
95	            if let Some(created_ms) = time_to_ms(created) {
96	                return created_ms;
97	            }
98	        }
99	        if let Ok(modified) = metadata.modified() {
100	            if let Some(modified_ms) = time_to_ms(modified) {
101	                return modified_ms;
102	            }
103	        }
104	    }
105	    0
106	}
107	
108	// ── Legacy migration ───────────────────────────────────────────────────────────
109	
110	fn migrate_legacy_folder_name(root: &Path, from_name: &str, to_name: &str) -> Result<(), String> {
111	    let from = root.join(from_name);
112	    if !from.exists() {
113	        return Ok(());
114	    }
115	    let to = root.join(to_name);
116	    if !to.exists() {
117	        fs::rename(&from, &to).map_err(|err| err.to_string())?;
118	        return Ok(());
119	    }
120	    for entry in fs::read_dir(&from).map_err(|err| err.to_string())? {
121	        let entry = entry.map_err(|err| err.to_string())?;
122	        let source = entry.path();
123	        let target = to.join(entry.file_name());
124	        if target.exists() {
125	            continue;
126	        }
127	        fs::rename(&source, &target).map_err(|err| err.to_string())?;
128	    }
129	    fs::remove_dir_all(&from).map_err(|err| err.to_string())?;
130	    Ok(())
131	}
132	
133	fn migrate_legacy_system_folders(root: &Path) -> Result<(), String> {
134	    migrate_legacy_folder_name(root, LEGACY_UNSORTED_FOLDER, FEED_FOLDER)?;
135	    migrate_legacy_folder_name(root, LEGACY_RECORDINGS_FOLDER, RECORDINGS_STORAGE_FOLDER)?;
136	    let feed_order = root.join(FEED_FOLDER).join(ORDER_FILE);
137	    if feed_order.exists() {
138	        let _ = fs::remove_file(feed_order);
139	    }
140	    Ok(())
141	}
142	
143	// ── System folders ─────────────────────────────────────────────────────────────
144	
145	/// True if the path is a direct child of root and a system folder.
146	pub(crate) fn is_system_folder_path(root: &Path, path: &Path) -> bool {
147	    if path.parent() != Some(root) {
148	        return false;
149	    }
150	    path.file_name()
151	        .and_then(|name| name.to_str())
152	        .is_some_and(is_system_folder_name)
153	}
154	
155	/// Check if a path falls inside a storage folder (recordings/attachments).
156	pub(crate) fn is_storage_folder_path(root: &Path, path: &Path) -> bool {
157	    path.starts_with(root.join(RECORDINGS_STORAGE_FOLDER))
158	        || path.starts_with(root.join(LEGACY_RECORDINGS_FOLDER))
159	        || path.starts_with(root.join(ATTACHMENTS_STORAGE_FOLDER))
160	}
161	
162	/// Create required system folders and ensure visible ones appear in the order file.
163	pub(crate) fn ensure_system_folders(root: &Path) -> Result<(), String> {
164	    migrate_legacy_system_folders(root)?;
165	
166	    for folder in REQUIRED_SYSTEM_FOLDERS {
167	        let path = root.join(folder);
168	        if path.exists() {
169	            continue;
170	        }
171	        fs::create_dir_all(&path).map_err(|err| {
172	            format!(
173	                "Failed to create system folder {}: {}",
174	                path.to_string_lossy(),
175	                err
176	            )
177	        })?;
178	    }
179	
180	    let mut order = read_order_file(root);
181	    let mut changed = false;
182	    for folder in VISIBLE_SYSTEM_FOLDERS {
183	        if !order.folder_order.iter().any(|name| name == folder) {
184	            order.folder_order.push(folder.to_string());
185	            changed = true;
186	        }
187	    }
188	
189	    if changed {
190	        write_order_file(root, &order)?;
191	    }
192	
193	    Ok(())
194	}
195	
196	// ── Folder tree ────────────────────────────────────────────────────────────────
197	
198	/// Recursively build the folder/note tree for the frontend sidebar.
199	pub(crate) fn build_folder_node(dir: &Path, rel_path: &str) -> Result<FolderNode, String> {
200	    let order = read_order_file(dir);
201	    let mut folders = Vec::new();
202	    let mut notes = Vec::new();
203	
204	    for entry in fs::read_dir(dir).map_err(|err| err.to_string())? {
205	        let entry = entry.map_err(|err| err.to_string())?;
206	        let path = entry.path();
207	        let name = entry.file_name().to_string_lossy().to_string();
208	        if name == ORDER_FILE {
209	            continue;
210	        }
211	        if rel_path.is_empty() && is_hidden_root_folder_name(&name) {
212	            continue;
213	        }
214	        let meta = entry.metadata().map_err(|err| err.to_string())?;
215	        if meta.is_dir() {
216	            folders.push(name);
217	        } else if meta.is_file() {
218	            if path.extension().and_then(|ext| ext.to_str()) == Some("md") {
219	                notes.push(name);
220	            }
221	        }
222	    }
223	
224	    let folder_names = sort_by_order(folders, &order.folder_order);
225	    let note_names = if rel_path == FEED_FOLDER {
226	        // Feed folder: sort by newest-first created timestamp.
227	        let mut feed_notes = notes
228	            .into_iter()
229	            .map(|name| {
230	                let created_ms = note_created_ms_for_sort(&dir.join(&name));
231	                (name, created_ms)
232	            })
233	            .collect::<Vec<_>>();
234	        feed_notes.sort_by(|(a_name, a_created), (b_name, b_created)| {
235	            b_created
236	                .cmp(a_created)
237	                .then_with(|| a_name.to_lowercase().cmp(&b_name.to_lowercase()))
238	        });
239	        feed_notes.into_iter().map(|(name, _)| name).collect()
240	    } else {
241	        sort_by_order(notes, &order.note_order)
242	    };
243	
244	    let mut children = Vec::new();
245	    for name in folder_names {
246	        let child_path = dir.join(&name);
247	        let child_rel = if rel_path.is_empty() {
248	            name.clone()
249	        } else {
250	            format!("{}/{}", rel_path, name)
251	        };
252	        children.push(build_folder_node(&child_path, &child_rel)?);
253	    }
254	
255	    let mut note_entries = Vec::new();
256	    for name in note_names {
257	        let note_rel = if rel_path.is_empty() {
258	            name.clone()
259	        } else {
260	            format!("{}/{}", rel_path, name)
261	        };
262	        note_entries.push(NoteEntry {
263	            name,
264	            path: note_rel,
265	        });
266	    }
267	
268	    Ok(FolderNode {
269	        name: if rel_path.is_empty() {
270	            "Notes".to_string()
271	        } else {
272	            dir.file_name()
273	                .and_then(|n| n.to_str())
274	                .unwrap_or("Folder")
275	                .to_string()
276	        },
277	        path: rel_path.to_string(),
278	        children,
279	        notes: note_entries,
280	    })
281	}
282	
283	// ── Order file I/O ─────────────────────────────────────────────────────────────
284	
285	/// Read the `.notes-order.json` from a directory, returning defaults if missing.
286	pub(crate) fn read_order_file(dir: &Path) -> OrderFile {
287	    let file_path = dir.join(ORDER_FILE);
288	    if let Ok(contents) = fs::read_to_string(file_path) {
289	        if let Ok(order) = serde_json::from_str::<OrderFile>(&contents) {
290	            return order;
291	        }
292	    }
293	    OrderFile::default()
294	}
295	
296	/// Persist the order file to disk (no-op for Feed folder, which sorts by date).
297	pub(crate) fn write_order_file(dir: &Path, order: &OrderFile) -> Result<(), String> {
298	    if dir
299	        .file_name()
300	        .and_then(|name| name.to_str())
301	        .is_some_and(|name| name == FEED_FOLDER)
302	    {
303	        return Ok(());
304	    }
305	    let file_path = dir.join(ORDER_FILE);
306	    let contents = serde_json::to_string_pretty(order).map_err(|err| err.to_string())?;
307	    fs::write(file_path, contents).map_err(|err| err.to_string())
308	}
309	
310	/// Remove entries from the folder or note order list.
311	pub(crate) fn update_order_remove(
312	    dir: &Path,
313	    names: &[String],
314	    is_folder: bool,
315	) -> Result<(), String> {
316	    let mut order = read_order_file(dir);
317	    if is_folder {
318	        order.folder_order.retain(|name| !names.contains(name));
319	    } else {
320	        order.note_order.retain(|name| !names.contains(name));
321	    }
322	    write_order_file(dir, &order)
323	}
324	
325	/// Append entries to the folder or note order list if not already present.
326	pub(crate) fn update_order_append(
327	    dir: &Path,
328	    names: &[String],
329	    is_folder: bool,
330	) -> Result<(), String> {
331	    let mut order = read_order_file(dir);
332	    let list = if is_folder {
333	        &mut order.folder_order
334	    } else {
335	        &mut order.note_order
336	    };
337	    for name in names {
338	        if !list.contains(name) {
339	            list.push(name.clone());
340	        }
341	    }
342	    write_order_file(dir, &order)
343	}
344	
345	/// Rename an entry in the order list (preserving its position).
346	pub(crate) fn update_order_rename(
347	    dir: &Path,
348	    old_name: &str,
349	    new_name: &str,
350	    is_folder: bool,
351	) -> Result<(), String> {
352	    let mut order = read_order_file(dir);
353	    let list = if is_folder {
354	        &mut order.folder_order
355	    } else {
356	        &mut order.note_order
357	    };
358	    if let Some(pos) = list.iter().position(|item| item == old_name) {
359	        list[pos] = new_name.to_string();
360	    }
361	    write_order_file(dir, &order)
362	}
363

