1	import {
2	  useCallback,
3	  useEffect,
4	  useMemo,
5	  useRef,
6	  useState,
7	  type Dispatch,
8	  type MouseEvent as ReactMouseEvent,
9	  type SetStateAction,
10	} from "react";
11	
12	import type { DesktopContextMenuState } from "@/app/hooks/use-tree-interactions";
13	import { FEED_FOLDER_PATH } from "@/shared/constants";
14	import { computeRangeSelection } from "@/shared/lib/selection";
15	import type { NotePreview } from "@/shared/lib/format";
16	import type { AppMode, NoteEntry } from "@/shared/types";
17	import type { FeedTreeNode } from "@/features/notes/navigation/model/feed-tree-model";
18	
19	type FolderSummary = {
20	  id: string;
21	};
22	
23	type UseDesktopNavigationArgs = {
24	  onAppModeChange: Dispatch<SetStateAction<AppMode>>;
25	  onOpenPinnedFolder: (path: string) => void;
26	  customFoldersTreeData: FolderSummary[];
27	  activeFolder: string;
28	  activeNote: string | null;
29	  activeFeedGroup: string;
30	  activeFeedNode: FeedTreeNode | null;
31	  feedNotes: Array<NoteEntry & { timestampMs: number }>;
32	  selectedNotes: Set<string>;
33	  lastSelectedNote: string;
34	  setSelectedFolders: Dispatch<SetStateAction<Set<string>>>;
35	  setLastSelectedFolder: (path: string) => void;
36	  setActiveFolder: (path: string) => void;
37	  setSelectedNotes: Dispatch<SetStateAction<Set<string>>>;
38	  setLastSelectedNote: (path: string) => void;
39	  setActiveNote: (path: string | null) => void;
40	  setActiveFeedGroup: (path: string) => void;
41	  clearNote: () => void;
42	  openDesktopContextMenu: (state: DesktopContextMenuState) => void;
43	  closeDesktopContextMenu: () => void;
44	  handleNoteClick: (
45	    notePath: string,
46	    event: ReactMouseEvent,
47	    parentPath?: string
48	  ) => void;
49	  handleNoteContextMenu: (
50	    event: ReactMouseEvent,
51	    notePath: string,
52	    parentPath?: string
53	  ) => Promise<void>;
54	  notes: NoteEntry[];
55	  notePreviews: Record<string, NotePreview>;
56	  activeNode: { name: string } | null;
57	  feedNotePreviews: Record<string, NotePreview>;
58	  deleteNotes: (paths: string[]) => Promise<boolean>;
59	};
60	
61	export function useDesktopNavigation({
62	  onAppModeChange,
63	  onOpenPinnedFolder,
64	  customFoldersTreeData,
65	  activeFolder,
66	  activeNote,
67	  activeFeedGroup,
68	  activeFeedNode,
69	  feedNotes,
70	  selectedNotes,
71	  lastSelectedNote,
72	  setSelectedFolders,
73	  setLastSelectedFolder,
74	  setActiveFolder,
75	  setSelectedNotes,
76	  setLastSelectedNote,
77	  setActiveNote,
78	  setActiveFeedGroup,
79	  clearNote,
80	  openDesktopContextMenu,
81	  closeDesktopContextMenu,
82	  handleNoteClick,
83	  handleNoteContextMenu,
84	  notes,
85	  notePreviews,
86	  activeNode,
87	  feedNotePreviews,
88	  deleteNotes,
89	}: UseDesktopNavigationArgs) {
90	  const [activeNavigationTab, setActiveNavigationTab] = useState<"feed" | "folders">(
91	    "folders"
92	  );
93	  // Feed is a transient view. Remember the last real folder so "back to folders"
94	  // has a stable place to land instead of guessing from the current tree.
95	  const lastNonFeedFolderRef = useRef<string>("");
96	  const selectedNotesRef = useRef<Set<string>>(new Set());
97	  selectedNotesRef.current = selectedNotes;
98	
99	  useEffect(() => {
100	    if (activeFolder && activeFolder !== FEED_FOLDER_PATH) {
101	      lastNonFeedFolderRef.current = activeFolder;
102	    }
103	  }, [activeFolder]);
104	
105	  useEffect(() => {
106	    if (activeFolder === FEED_FOLDER_PATH && activeNavigationTab !== "feed") {
107	      setActiveNavigationTab("feed");
108	      return;
109	    }
110	    if (activeFolder !== FEED_FOLDER_PATH && activeNavigationTab === "feed") {
111	      setActiveNavigationTab("folders");
112	    }
113	  }, [activeFolder, activeNavigationTab]);
114	
115	  const deleteSelectedNotesByShortcut = useCallback(() => {
116	    const selected = selectedNotesRef.current;
117	    const paths =
118	      activeNote && !selected.has(activeNote)
119	        ? [activeNote]
120	        : selected.size > 0
121	          ? Array.from(selected)
122	          : activeNote
123	            ? [activeNote]
124	            : [];
125	    if (paths.length > 0) {
126	      void deleteNotes(paths);
127	    }
128	  }, [activeNote, deleteNotes]);
129	
130	  const openFeedTab = useCallback(() => {
131	    closeDesktopContextMenu();
132	    onAppModeChange("notes");
133	    if (activeFolder && activeFolder !== FEED_FOLDER_PATH) {
134	      lastNonFeedFolderRef.current = activeFolder;
135	    }
136	    setActiveNavigationTab("feed");
137	    onOpenPinnedFolder(FEED_FOLDER_PATH);
138	  }, [activeFolder, closeDesktopContextMenu, onAppModeChange, onOpenPinnedFolder]);
139	
140	  const openFoldersTab = useCallback(() => {
141	    closeDesktopContextMenu();
142	    onAppModeChange("notes");
143	    setActiveNavigationTab("folders");
144	    const fallbackFolder =
145	      lastNonFeedFolderRef.current || customFoldersTreeData[0]?.id || "";
146	    if (fallbackFolder) {
147	      onOpenPinnedFolder(fallbackFolder);
148	      return;
149	    }
150	    setSelectedFolders(new Set());
151	    setLastSelectedFolder("");
152	    setSelectedNotes(new Set());
153	    setLastSelectedNote("");
154	    setActiveFolder("");
155	    setActiveNote(null);
156	    clearNote();
157	  }, [
158	    clearNote,
159	    closeDesktopContextMenu,
160	    customFoldersTreeData,
161	    onAppModeChange,
162	    onOpenPinnedFolder,
163	    setActiveFolder,
164	    setActiveNote,
165	    setLastSelectedFolder,
166	    setLastSelectedNote,
167	    setSelectedFolders,
168	    setSelectedNotes,
169	  ]);
170	
171	  const handleFeedMiddleNoteClick = useCallback(
172	    (notePath: string, event: ReactMouseEvent) => {
173	      const notePaths = feedNotes.map((note) => note.path);
174	      setSelectedNotes(
175	        computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
176	      );
177	      setLastSelectedNote(notePath);
178	      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
179	      setLastSelectedFolder(FEED_FOLDER_PATH);
180	      setActiveFolder(FEED_FOLDER_PATH);
181	      setActiveNote(notePath);
182	      setActiveFeedGroup(activeFeedGroup || activeFeedNode?.id || "");
183	      setActiveNavigationTab("feed");
184	    },
185	    [
186	      activeFeedGroup,
187	      activeFeedNode?.id,
188	      feedNotes,
189	      lastSelectedNote,
190	      setActiveFeedGroup,
191	      setActiveFolder,
192	      setActiveNote,
193	      setLastSelectedFolder,
194	      setLastSelectedNote,
195	      setSelectedFolders,
196	      setSelectedNotes,
197	      selectedNotes,
198	    ]
199	  );
200	
201	  const handleFeedMiddleNoteContextMenu = useCallback(
202	    (event: ReactMouseEvent, notePath: string) => {
203	      event.preventDefault();
204	      event.stopPropagation();
205	      const notePaths = feedNotes.map((note) => note.path);
206	      const targetPaths =
207	        selectedNotes.size > 1 && selectedNotes.has(notePath)
208	          ? Array.from(selectedNotes)
209	          : [notePath];
210	      setSelectedFolders(new Set([FEED_FOLDER_PATH]));
211	      setLastSelectedFolder(FEED_FOLDER_PATH);
212	      setActiveFolder(FEED_FOLDER_PATH);
213	      if (!selectedNotes.has(notePath)) {
214	        setSelectedNotes(new Set([notePath]));
215	        setLastSelectedNote(notePath);
216	      }
217	      setActiveNote(notePath);
218	      setActiveFeedGroup(activeFeedGroup || activeFeedNode?.id || "");
219	      setActiveNavigationTab("feed");
220	      openDesktopContextMenu({
221	        kind: "note",
222	        x: event.clientX,
223	        y: event.clientY,
224	        path: notePath,
225	        parentPath: activeFeedGroup || activeFeedNode?.id || FEED_FOLDER_PATH,
226	        targetPaths: targetPaths.length > 0 ? targetPaths : notePaths,
227	      });
228	    },
229	    [
230	      activeFeedGroup,
231	      activeFeedNode?.id,
232	      feedNotes,
233	      openDesktopContextMenu,
234	      selectedNotes,
235	      setActiveFeedGroup,
236	      setActiveFolder,
237	      setActiveNote,
