cat > /tmp/feed-perf.test.ts <<'EOF'
import { describe, it } from "vitest";
import { buildFeedTree } from "@/features/notes/navigation/model/feed-tree-model";
import type { NotePreview } from "@/shared/lib/format";
import type { NoteEntry } from "@/shared/types";

const makeVault = (count: number) => {
  const notes: NoteEntry[] = [];
  const previews: Record<string, NotePreview> = {};
  const now = Date.now();
  for (let i = 0; i < count; i += 1) {
    const path = `Feed/note-${i}.md`;
    notes.push({ name: `note-${i}.md`, path });
    // spread notes over ~2 years
    const ts = now - Math.floor((i / count) * 730) * 86_400_000;
    previews[path] = {
      title: `t${i}`, dateLabel: "", secondLine: "",
      createdMs: ts, updatedMs: ts, archivedMs: null, reviewedMs: null,
      isArchived: false, isReviewed: false, isRecording: false, isHandwriting: false,
      recordingAudioPath: null, handwritingAttachmentPath: null,
      transcriptionStatus: null, ocrStatus: null,
    };
  }
  return { notes, previews };
};

describe("feed perf", () => {
  it("times buildFeedTree", () => {
    for (const count of [1000, 3000]) {
      const { notes, previews } = makeVault(count);
      buildFeedTree(notes, previews, false); // warm up
      const t0 = performance.now();
      buildFeedTree(notes, previews, false);
      const t1 = performance.now();
      console.log(`buildFeedTree ${count} notes: ${(t1 - t0).toFixed(1)}ms`);
    }
  });
});
EOF
cp /tmp/feed-perf.test.ts src/feed-perf.test.ts && npx vitest run src/feed-perf.test.ts 2>&1 | grep -E "buildFeedTree|passed|failed"

